  const seed = getMotionSeed(id)
  const phase = seed.phase + motionTimeRef.current * seed.speed
  return {
    x: base.x + Math.sin(phase) * seed.amplitude,
    y: base.y + Math.cos(phase * 0.9) * seed.amplitude,
